function 阶梯(值, 分界, 末段) {
    for (const [上限, 名称] of 分界) {
        if (值 < 上限)
            return 名称;
    }
    return 末段;
}
const 百分比 = z.coerce
    .number()
    .catch(0)
    .transform(值 => _.clamp(Math.round(值), 0, 100));
const 计数 = z.coerce
    .number()
    .catch(0)
    .transform(值 => Math.max(0, Math.round(值)));
const 孕期 = z.enum(['无', '小孕肚', '大孕肚']).catch('无');
const 着装 = z.record(z.string().describe('部位'), z.string().describe('这一部位的穿着')).catch({});
const 女主 = (分界, 末段) => z
    .object({
    堕落度: 百分比,
    孕期: 孕期,
    发情度: 百分比,
    体力: 百分比,
    好感度: 百分比,
    着装: 着装,
    当前态度: z.string().catch('未定'),
    与德里克: z.string().catch('未定'),
})
    .transform(数据 => ({ ...数据, $阶段: 阶梯(数据.堕落度, 分界, 末段) }));
export const Schema = z.object({
    世界: z.object({
        日期: z.string().catch('第 1 天'),
        时段: z.string().catch('清晨'),
        地点: z.string().catch('家'),
        天气: z.string().catch('晴'),
        主线进度: z.string().catch('开局'),
        近期事件: z.record(z.string().describe('事件名'), z.string().describe('事件描述')).catch({}),
        回想: z.record(z.string().describe('场景名'), z.string().describe('一句话回顾')).catch({}),
    }),
    妈妈: 女主([[20, '持家'], [40, '动摇'], [60, '沉沦'], [80, '忘我']], '黑人新娘'),
    姐姐: 女主([[20, '高岭'], [40, '戒备'], [60, '破防'], [80, '沉溺']], '淫堕'),
    德里克: z.object({
        掌控度: 百分比,
        留宿次数: 计数,
        当前目标: z.string().catch('未定'),
    }),
    主角: z.object({
        心境: z.string().catch('平静'),
        兴奋度: 百分比,
        羞耻度: 百分比,
        证物: z
            .record(z.string().describe('证物名'), z.object({ 描述: z.string().catch('') }))
            .catch({})
            .transform(数据 => _.pickBy(数据, ({ 描述 }) => Boolean(描述))),
        已知情报: z.record(z.string().describe('情报名'), z.string().describe('情报内容')).catch({}),
    }),
});
